cd /app; python3 - <<'EOF'
import csv, json, collections
from datetime import datetime, timezone
def rd(p): return list(csv.DictReader(open(p)))
def T(s): return datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
plan={r['run_id']:r for r in rd('plan.csv')}
lm={r['run_id']:r for r in rd('launch_log.csv')}
E={r['run_id']:float(r['pass_rate']) for r in rd('eval_results.csv')}
R={r['run_id']:T(r['finished_at']) for r in rd('runtime.csv')}
RL={r['run_id']:r for r in rd('retention_log.csv')}
rec={}
for i in range(4):
    for r in rd(f'recovered/shard_0{i}.csv'): rec[r['run_id']]=round(float(r['pass_rate_pct'])/100,4)
L=set(lm); val={**E,**{k:v for k,v in rec.items() if k in L}}; free=L-set(val)
print('latest retention drop:',max(r['dropped_at'] for r in RL.values()), 'r00003:',RL['r00003']['dropped_at'])
print('latest finish:',max(R.values()))
# surviving eval rows <0.27 finished before 06-27: finish dates
print(sorted(R[k].strftime('%m-%d') for k,v in E.items() if v<0.27 and R[k]<T('2026-06-27T00:00:00Z')))
# free runs per category & suite
cat=collections.Counter((plan[k]['suite'], RL[k]['reason'] if k in RL else 'outage') for k in free)
for k,v in sorted(cat.items()): print(k,v)
# b01 cell free runs: workers/dates
c={'suite':'arc_lite','curriculum':'c2','retrieval':'dense','decoder':'greedy'}
ks=[k for k in L if all(plan[k][f]==c[f] for f in c)]
print('b01 free:',collections.Counter((lm[k]['worker'], 'ret' if k in RL else 'out') for k in ks if k in free))
EOF
